<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Book appointment | MedTech</title>
<link rel="stylesheet" href="vendor/bootstrap/css/bootstrap.min.css"><link rel="stylesheet" href="vendor/fontawesome/css/font-awesome.min.css"><link rel="stylesheet" href="vendor/themify-icons/themify-icons.min.css"><link rel="stylesheet" href="assets/css/styles.css"><link rel="stylesheet" href="assets/css/plugins.css"><link rel="stylesheet" href="assets/css/themes/theme-1.css" /><link rel="stylesheet" href="assets/css/medtech-app.css"></head><body><div id="app"><?php include 'include/sidebar.php';?><div class="app-content"><?php include 'include/header.php';?><div class="main-content"><div class="wrap-content container" id="container"><section id="page-title"><h1 class="mainTitle">Book an appointment</h1></section><div class="container-fluid container-fullw bg-white"><div class="mt-booking-card"><div class="mt-booking-steps"><span><b>01</b> Choose care</span><span><b>02</b> Select doctor</span><span><b>03</b> Pick a time</span><span><b>04</b> Send request</span></div><p class="hms-alert">Choose from your doctor's published availability. Requests are sent to the doctor for confirmation.</p>
<form method="post" id="booking-form"><?php echo hms_csrf_field();?><div class="form-group"><label for="specialization">Specialization</label><select id="specialization" class="form-control" required><option value="">Select specialization</option><?php while($s=$specializations->fetch_assoc()):?><option value="<?=hms_h($s['specilization'])?>"><?=hms_h($s['specilization'])?></option><?php endwhile;?></select></div>
<div class="form-group"><label for="doctor">Doctor</label><select id="doctor" name="doctor" class="form-control" required disabled><option value="">Select specialization first</option></select></div>
<div class="form-group"><label for="fees">Consultancy fee</label><input id="fees" class="form-control" readonly value="Select a doctor"></div><div class="form-group"><label for="appdate">Date</label><input id="appdate" name="appdate" type="date" class="form-control" min="<?=date('Y-m-d')?>" required></div>
<div class="form-group"><label for="apptime">Available time</label><select id="apptime" name="apptime" class="form-control" required disabled><option value="">Select doctor and date first</option></select></div>
<div class="form-group"><label for="visit_reason">Reason for visit</label><textarea id="visit_reason" name="visit_reason" class="form-control" rows="4" maxlength="1000" required></textarea><small class="hms-help">Share a short description to help the care team prepare.</small></div><button class="btn btn-primary" type="submit">Request appointment</button></form></div></div></div></div><?php include 'include/footer.php';?></div></div>
<script src="vendor/jquery/jquery.min.js"></script><script src="vendor/bootstrap/js/bootstrap.min.js"></script><script src="assets/js/main.js"></script><script>
const spec=document.getElementById('specialization'),doctor=document.getElementById('doctor'),date=document.getElementById('appdate'),slot=document.getElementById('apptime');
spec.addEventListener('change',async()=>{doctor.innerHTML='<option value="">Loading…</option>';doctor.disabled=true;slot.innerHTML='<option value="">Select doctor and date first</option>';try{const r=await fetch('get_doctor.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'specilizationid='+encodeURIComponent(spec.value)});doctor.innerHTML=await r.text();doctor.disabled=false;}catch(e){doctor.innerHTML='<option value="">Unable to load doctors</option>';}});
async function loadSlots(){slot.disabled=true;slot.innerHTML='<option value="">Loading available times…</option>';if(!doctor.value||!date.value){slot.innerHTML='<option value="">Select doctor and date first</option>';return;}try{const r=await fetch('available-slots.php?doctor_id='+encodeURIComponent(doctor.value)+'&date='+encodeURIComponent(date.value));const data=await r.json();slot.innerHTML='<option value="">Select an available time</option>';for(const item of data.slots||[]){const o=document.createElement('option');o.value=item.value;o.textContent=item.label;slot.append(o);}if(!data.slots?.length)slot.innerHTML='<option value="">No appointments available for this date</option>';else slot.disabled=false;}catch(e){slot.innerHTML='<option value="">Times could not be loaded</option>';}}
doctor.addEventListener('change',async()=>{loadSlots();const fee=document.getElementById('fees');fee.value='';if(doctor.value){try{const r=await fetch('get_doctor.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'doctor='+encodeURIComponent(doctor.value)});const box=document.createElement('div');box.innerHTML=await r.text();fee.value=box.querySelector('option[value]')?.value||'Not available';}catch(e){fee.value='Not available';}}});date.addEventListener('change',loadSlots);</script></body></html>
